// Only jobs not returned in earlier runs come back.
const rows = $input.all().map((i) => i.json).filter((j) => j.title);
if (!rows.length) return [];
const lines = rows.slice(0, 20).map((j) => `• <${j.applyUrl || j.jobUrl}|${j.title}> at ${j.companyName || '?'}, ${j.location || ''}${j.salaryText ? ` · ${j.salaryText}` : ''}`);
return [{ json: { message: `🆕 ${rows.length} new job${rows.length === 1 ? '' : 's'}:\n${lines.join('\n')}` } }];
